CREATE TABLE subscriptions(user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,plan TEXT NOT NULL,status TEXT NOT NULL,source TEXT NOT NULL,started_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,canceled_at TEXT,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE businesses(user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,payload TEXT NOT NULL,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE partners(id TEXT PRIMARY KEY,status TEXT NOT NULL DEFAULT 'draft',payload TEXT NOT NULL CHECK(json_valid(payload)),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE referrals(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,partner_id TEXT NOT NULL REFERENCES partners(id),consent_id TEXT NOT NULL REFERENCES consents(id),need TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',payload TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX referrals_owner ON referrals(user_id);
CREATE INDEX referrals_partner ON referrals(partner_id);
CREATE TABLE analytics_events(id TEXT PRIMARY KEY,subject TEXT NOT NULL,name TEXT NOT NULL,props TEXT NOT NULL DEFAULT '{}',day TEXT NOT NULL);
CREATE INDEX analytics_day ON analytics_events(day,name);
CREATE TABLE audit_events(id TEXT PRIMARY KEY,subject TEXT NOT NULL,action TEXT NOT NULL,meta TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX audit_created ON audit_events(created_at);
